// Illustrations from static/art (manifest generated by design/art/tools/process.py).
import manifestJson from '../../../../static/art/manifest.json';
import picsEmojiJson from '../../../../static/art/pics-emoji.json';
import type { Level, Theme } from '../../types.ts';

export interface ArtVariant {
  width: number;
  path: string;
}

export interface ArtEntry {
  path: string;
  width: number;
  height: number;
  alt: string;
  group: string;
  transparent: boolean;
  variants?: ArtVariant[];
}

export const MANIFEST = manifestJson as Record<string, ArtEntry>;

export type ArtKey = keyof typeof manifestJson;

export function art(key: string): ArtEntry | undefined {
  return MANIFEST[key];
}

/** `srcset` with the smaller variants and the original, or undefined when there are no variants. */
export function srcsetOf(entry: ArtEntry): string | undefined {
  if (!entry.variants?.length) return undefined;
  return [...entry.variants.map((v) => `${v.path} ${v.width}w`), `${entry.path} ${entry.width}w`].join(', ');
}

/** Smallest variant that still covers `px` CSS pixels at 2× density (icons without `sizes`). */
export function pathFor(entry: ArtEntry, px: number): string {
  const need = px * 2;
  const fit = (entry.variants ?? []).filter((v) => v.width >= need).sort((a, b) => a.width - b.width)[0];
  return fit ? fit.path : entry.path;
}

// --- Avatars ---------------------------------------------------------------------------------

/** Player avatar stored as text: an emoji (older data) or `art:<animal>` for an illustrated animal. */
export const ART_AVATAR_PREFIX = 'art:';

export const ART_AVATARS: readonly string[] = Object.keys(MANIFEST)
  .filter((k) => k.startsWith('avatars.'))
  .map((k) => ART_AVATAR_PREFIX + k.slice('avatars.'.length));

export function avatarArt(value: string | null | undefined): ArtEntry | undefined {
  if (!value || !value.startsWith(ART_AVATAR_PREFIX)) return undefined;
  return MANIFEST[`avatars.${value.slice(ART_AVATAR_PREFIX.length)}`];
}

/** Animal name for an illustrated avatar („Liška“), undefined for emoji. */
export function avatarName(value: string | null | undefined): string | undefined {
  return avatarArt(value)?.alt.replace(/^Avatar hráče:\s*/, '');
}

/** Text form for places that only take text (TTS, title): emoji stays, art avatars become empty. */
export function avatarText(value: string | null | undefined): string {
  if (!value) return '';
  return value.startsWith(ART_AVATAR_PREFIX) ? '' : value;
}

/** First illustrated avatar nobody uses yet. */
export function freeArtAvatar(used: Iterable<string>): string {
  const taken = new Set(used);
  return ART_AVATARS.find((a) => !taken.has(a)) ?? ART_AVATARS[taken.size % ART_AVATARS.length];
}

