/** Own art when the manifest has it, otherwise the closest existing level picture. */
function levelArtKey(level: string, fallback: string): string {
  return `levels.${level}` in MANIFEST ? `levels.${level}` : fallback;
}

export const LEVEL_ART: Record<Level | 'vsichni', string> = {
  kocarek: levelArtKey('kocarek', 'levels.piskoviste'),
  piskoviste: 'levels.piskoviste',
  prvnacek: levelArtKey('prvnacek', 'levels.lavice'),
  lavice: 'levels.lavice',
  hospoda: 'levels.hospoda',
  vsichni: 'levels.vsichni',
};

/** Medal for places 1–3 in standings and the league. */
export function medalArt(place: number): string | undefined {
  return place >= 1 && place <= 3 ? `rewards.misto-${place}` : undefined;
}

// --- Picture dictionary for children's questions (static/art/pics) ------------------------------

/** Emoji used in the question data → picture key (`🐐` → `koza`), generated by process.py. */
export const PICS_EMOJI = picsEmojiJson as Record<string, string>;

const VARIATION_SELECTOR = /\uFE0F/g;

/** Manifest entry of a picture by its key (`koza`) or undefined. */
export function picArt(key: string | null | undefined): ArtEntry | undefined {
  return key ? MANIFEST[`pics.${key}`] : undefined;
}

/** Picture key for an emoji, tolerant to the U+FE0F variation selector; undefined without a picture. */
export function picKeyFor(emoji: string | null | undefined): string | undefined {
  if (!emoji) return undefined;
  const e = emoji.trim();
  return PICS_EMOJI[e] ?? PICS_EMOJI[e.replace(VARIATION_SELECTOR, '')] ?? PICS_EMOJI[e + '\uFE0F'];
}

const LEADING_EMOJI = /^\s*((?:\p{Extended_Pictographic}|\p{Regional_Indicator}|[0-9#*]\uFE0F?\u20E3)(?:\uFE0F|\u200D(?:\p{Extended_Pictographic})\uFE0F?|\p{Emoji_Modifier})*)\s*/u;

/** Splits an option like „🐶 Pejsek“ into its leading emoji and the label („Pejsek“). */
export function splitEmoji(text: string): { emoji: string; label: string } {
  const m = LEADING_EMOJI.exec(text);
  return m ? { emoji: m[1], label: text.slice(m[0].length) } : { emoji: '', label: text };
}

/** All picture keys in manifest order (gallery, data checks). */
export const PIC_KEYS: readonly string[] = Object.keys(MANIFEST)
  .filter((k) => k.startsWith('pics.'))
  .map((k) => k.slice('pics.'.length));

